; =====================================================================
;  HyperBoot - stage 1 bootloader generated by Hyper OS Creator
; ---------------------------------------------------------------------
;  * Fits in a single 512 byte boot sector.
;  * Prints a coloured banner, then loads N sectors (starting at LBA 1)
;    from the boot drive into 0x1000:0000 and jumps there.
;  * Works from a floppy image, a raw disk image or an El Torito
;    (floppy emulation) CD - the disk geometry is queried from the BIOS.
;
;  The config block right after the jump is patched by Hyper OS Creator
;  so you can change the banner, colour and kernel size without NASM.
;
;  Build manually:  nasm -f bin hyperboot.asm -o hyperboot.bin
; =====================================================================
bits 16
org 0x7C00

KERNEL_SEG equ 0x1000

start:
    jmp short main
    nop

; ---------------- config block (offsets are relative to sector start)
cfg_magic:   db 'HYPB'          ; +3  magic
cfg_sectors: dw 32              ; +7  sectors to load (kernel size)
cfg_attr:    db 0x1F            ; +9  banner colour (VGA attribute)
cfg_flags:   db 0               ; +10 bit0: wait for a key before boot
cfg_msg:     db 'HyperBoot', 0  ; +11 banner text (max 63 chars + NUL)
             times (64 - ($ - cfg_msg)) db 0

main:
    cli
    xor ax, ax
    mov ds, ax
    mov es, ax
    mov ss, ax
    mov sp, 0x7C00
    sti
    cld
    mov [boot_drive], dl

    mov ax, 0x0003              ; 80x25 colour text mode (clears screen)
    int 0x10

    ; ---- banner via INT 10h/AH=13h (write string with attribute)
    mov si, cfg_msg
    xor cx, cx
.len:
    lodsb
    test al, al
    jz .gotlen
    inc cx
    jmp .len
.gotlen:
    mov bp, cfg_msg
    mov ax, 0x1301
    xor bh, bh
    mov bl, [cfg_attr]
    xor dx, dx
    int 0x10

    mov si, msg_loading
    call print

    ; ---- ask the BIOS for the drive geometry (fallback 18/2)
    mov ah, 0x08
    mov dl, [boot_drive]
    xor di, di
    int 0x13
    jc .geo_done
    and cl, 0x3F
    jz .geo_done
    mov [spt], cl
    inc dh
    mov [heads], dh
.geo_done:

    ; ---- load the kernel
    mov ax, KERNEL_SEG
    mov es, ax
    xor bx, bx
    mov ax, 1                   ; first kernel sector (LBA)
    mov cx, [cfg_sectors]
.read_loop:
    call read_lba
    inc ax
    mov dx, es
    add dx, 0x20                ; next 512 bytes
    mov es, dx
    loop .read_loop

    test byte [cfg_flags], 1
    jz .boot
    mov si, msg_key
    call print
    xor ax, ax
    int 0x16

.boot:
    mov dl, [boot_drive]
    mov ax, KERNEL_SEG
    mov ds, ax
    mov es, ax
    jmp KERNEL_SEG:0x0000

; ---------------------------------------------------------------------
; read_lba: read sector AX into ES:BX (all registers preserved)
read_lba:
    pusha
    xor dx, dx
    movzx cx, byte [spt]
    div cx                      ; ax = lba / spt, dx = lba % spt
    mov si, dx
    inc si                      ; sector (1 based)
    xor dx, dx
    movzx cx, byte [heads]
    div cx                      ; ax = cylinder, dx = head
    mov dh, dl
    mov ch, al
    mov cl, ah
    shl cl, 6
    mov ax, si
    or cl, al
    mov dl, [boot_drive]
    mov di, 4                   ; retries
.retry:
    mov ax, 0x0201
    int 0x13
    jnc .ok
    xor ah, ah                  ; reset disk and retry
    int 0x13
    dec di
    jnz .retry
    mov si, msg_err
    call print
.hang:
    cli
    hlt
    jmp .hang
.ok:
    mov ax, 0x0E2E              ; progress dot
    xor bx, bx
    int 0x10
    popa
    ret

; print: DS:SI zero terminated string via BIOS teletype
print:
    pusha
    mov ah, 0x0E
    xor bx, bx
.p:
    lodsb
    test al, al
    jz .e
    int 0x10
    jmp .p
.e:
    popa
    ret

msg_loading: db 13, 10, 'Loading', 0
msg_key:     db 13, 10, 'Press any key to boot...', 0
msg_err:     db 13, 10, 'Disk read error!', 0
boot_drive:  db 0
spt:         db 18
heads:       db 2

    times 510 - ($ - $$) db 0
    dw 0xAA55
